glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out vec4 v_thisPos;
out vec4 v_sytrPos;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
out vec2 v_rawUV0;
#endif
uniform PointData {
  vec4 u_uvOffset;
  vec2 firstPos;
  vec2 secondPos;
  float u_uvRotated;
  float shadowDis;
  float mode;
  float p;
};
vec2 getSymmetricPos(vec2 sp,vec2 pos1, vec2 pos2)
{
  float disX = pos2.x - pos1.x;
  float disY = pos2.y - pos1.y;
  float k1 = disY/disX;
  float y = (sp.y*k1*k1  + sp.x*k1 + k1*sp.x - k1*pos1.x*2.0 + pos1.y*2.0 - sp.y)/(1.0+k1*k1);
  float x = (y - sp.y)/(-1.0/k1)+sp.x;
  return vec2(x,y);
}
void main () {
  vec4 pos = vec4(a_position,1.0);
  vec4 shadowPos = vec4(a_position,1.0);
  v_thisPos = vec4(pos);
  float pp = 0.5;
  if(mode > 0.0){
    pp = pp + 0.5 * p;
  }
  vec2 pos1 = vec2(firstPos.x + (secondPos.x - firstPos.x)*0.5 , firstPos.y + (secondPos.y - firstPos.y)*0.5);
  vec2 pos3 = vec2(firstPos.x + (secondPos.x - firstPos.x)*pp , firstPos.y + (secondPos.y - firstPos.y)*pp);
  vec2 sp = vec2( pos.x , pos.y );
  if (secondPos.y - firstPos.y == 0.0)
  {
    float x = pos1.x - sp.x + pos1.x;
    if (sp.x > pos1.x){
      x = pos1.x - (sp.x - pos1.x );
    }
    pos.x = x;
    shadowPos.x = pos.x;
    if(mode > 0.0){
      shadowPos.x = secondPos.x;
    }
    pos.y = sp.y;
    shadowPos.y = pos.y;
  }else{
    float k = ( secondPos.y - firstPos.y)/(secondPos.x - firstPos.x);
    k = -1.0/k;
    float b = pos1.y -  k*pos1.x;
    vec2 pos2 = vec2(0,b);
    vec2 symmetricPos = getSymmetricPos(sp,pos1,pos2);
    pos.x = symmetricPos.x;
    pos.y = symmetricPos.y;
    float b2 = pos3.y -  k*pos3.x;
    vec2 pos4 = vec2(0,b2);
    symmetricPos = getSymmetricPos(sp,pos3,pos4);
    shadowPos.x = symmetricPos.x;
    shadowPos.y = symmetricPos.y;
  }
  v_sytrPos = vec4(shadowPos);
  if (secondPos.y  < firstPos.y){
      pos.y = pos.y + 1.0;
  }else if (secondPos.y > firstPos.y){
      pos.y = pos.y - 1.0;
  }
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos ;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in vec4 v_thisPos;
in vec4 v_sytrPos;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform PointData {
  vec4 u_uvOffset;
  vec2 firstPos;
  vec2 secondPos;
  float u_uvRotated;
  float shadowDis;
  float mode;
  float p;
};
bool isHide(){
  if (secondPos.y == firstPos.y){
    float xw = (secondPos.x - firstPos.x)*0.5;
    if (  xw > 0.0 ){
      if(mode == 0.0 && v_thisPos.x < xw + firstPos.x){
        return true;
      }
      if(mode > 0.0 && v_thisPos.x < secondPos.x){
        return true;
      }
    }else if (xw < 0.0){
      if(mode == 0.0 && v_thisPos.x > xw + firstPos.x){
        return true;
      }
      if(mode > 0.0 && v_thisPos.x > secondPos.x){
        return true;
      }
    }
  }
  float k = ( secondPos.y - firstPos.y)/(secondPos.x - firstPos.x);
  k = -1.0/k;
  float pp = 0.5;
  if(mode > 0.0){
    pp = pp + 0.5 * p;
  }
  float b = (firstPos.y + (secondPos.y - firstPos.y)*pp) -  k* (firstPos.x +(secondPos.x - firstPos.x)*pp);
  float y = k*v_thisPos.x + b;
  if (secondPos.y  < firstPos.y && v_thisPos.y > y){
      return true;
  }else if (secondPos.y > firstPos.y && v_thisPos.y < y){
      return true;
  }
  return false;
}
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  o *= v_color;
  vec4 backgroundColor = vec4(1.0, 1.0, 1.0, o.a);
  vec2 uvOffset;
  uvOffset.x = (v_uv0.x-u_uvOffset.x)/(u_uvOffset.z-u_uvOffset.x);
  uvOffset.y = (v_uv0.y-u_uvOffset.y)/(u_uvOffset.w-u_uvOffset.y);
  if(u_uvRotated > 0.5) {
    float temp = uvOffset.x;
    uvOffset.x = uvOffset.y;
    uvOffset.y = 1.0 - temp;
  }
  bool isCornerChar = ((uvOffset.x >0.85 && uvOffset.y > 0.82) || (uvOffset.y < 0.18 && uvOffset.x < 0.15));
  if (isCornerChar && mode == 0.0) {
      o = backgroundColor;
  }
  float disX = v_sytrPos.x - v_thisPos.x;
  float disY = v_sytrPos.y - v_thisPos.y;
  float disTCur = sqrt(disX*disX+disY*disY)*0.5;
  if (disTCur < shadowDis && mode != 3.0){
    float rgbNum = 0.1;
    rgbNum = rgbNum + (1.0 - rgbNum)*disTCur/shadowDis;
    o = o*vec4(rgbNum,rgbNum,rgbNum,1.0);
  }
  ALPHA_TEST(o);
  if (!isHide()){
    o.a = 0.0;
  }
  gl_FragColor = o;
}

